-- Produits, fournisseurs et mouvements validés : socle métier SWAY.
create table public.suppliers (id uuid primary key default gen_random_uuid(), establishment_id uuid not null references public.establishments(id) on delete cascade, name text not null, email text, phone text, active boolean not null default true, created_by uuid not null references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(establishment_id,name));
create table public.products (id uuid primary key default gen_random_uuid(), establishment_id uuid not null references public.establishments(id) on delete cascade, name text not null, category text not null default 'Autres', unit text not null default 'unité', low_stock_threshold numeric not null default 0 check(low_stock_threshold>=0), active boolean not null default true, metadata jsonb not null default '{}'::jsonb check(jsonb_typeof(metadata)='object'), created_by uuid not null references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(establishment_id,name));
create table public.product_suppliers (product_id uuid not null references public.products(id) on delete cascade, supplier_id uuid not null references public.suppliers(id) on delete cascade, supplier_sku text, price numeric check(price>=0), pack_quantity numeric not null default 1 check(pack_quantity>0), is_preferred boolean not null default false, primary key(product_id,supplier_id));
create table public.stock_positions (establishment_id uuid not null references public.establishments(id) on delete cascade, product_id uuid not null references public.products(id) on delete cascade, location text not null default 'principal', quantity numeric not null default 0 check(quantity>=0), updated_by uuid not null references public.profiles(id), updated_at timestamptz not null default now(), primary key(establishment_id,product_id,location));
create table public.stock_movements (id uuid primary key default gen_random_uuid(), establishment_id uuid not null references public.establishments(id) on delete cascade, product_id uuid not null references public.products(id) on delete restrict, location text not null default 'principal', quantity_delta numeric not null check(quantity_delta<>0), movement_type text not null check(movement_type in ('reception','inventory_validation','external_sale','loss','gift','cancellation','adjustment')), source_type text, source_id text, reason text, validated_by uuid not null references public.profiles(id), validated_at timestamptz not null default now(), created_at timestamptz not null default now());
alter table public.suppliers enable row level security; alter table public.products enable row level security; alter table public.product_suppliers enable row level security; alter table public.stock_positions enable row level security; alter table public.stock_movements enable row level security;
revoke all on public.suppliers,public.products,public.product_suppliers,public.stock_positions,public.stock_movements from anon,authenticated; grant select on public.suppliers,public.products,public.product_suppliers,public.stock_positions,public.stock_movements to authenticated; grant insert,update on public.suppliers,public.products,public.product_suppliers,public.stock_positions to authenticated; grant insert on public.stock_movements to authenticated;
create policy "Members can read suppliers" on public.suppliers for select to authenticated using ((select private.is_establishment_member(establishment_id)));
create policy "Management can create suppliers" on public.suppliers for insert to authenticated with check (created_by=(select auth.uid()) and (select private.has_establishment_role(establishment_id,array['administrateur','gestion']::public.app_role[])));
create policy "Management can update suppliers" on public.suppliers for update to authenticated using ((select private.has_establishment_role(establishment_id,array['administrateur','gestion']::public.app_role[]))) with check ((select private.has_establishment_role(establishment_id,array['administrateur','gestion']::public.app_role[])));
create policy "Members can read products" on public.products for select to authenticated using ((select private.is_establishment_member(establishment_id)));
create policy "Management can create products" on public.products for insert to authenticated with check (created_by=(select auth.uid()) and (select private.has_establishment_role(establishment_id,array['administrateur','gestion']::public.app_role[])));
create policy "Management can update products" on public.products for update to authenticated using ((select private.has_establishment_role(establishment_id,array['administrateur','gestion']::public.app_role[]))) with check ((select private.has_establishment_role(establishment_id,array['administrateur','gestion']::public.app_role[])));
create policy "Members can read product suppliers" on public.product_suppliers for select to authenticated using ((select private.is_establishment_member((select establishment_id from public.products where id=product_id))));
create policy "Management can manage product suppliers" on public.product_suppliers for all to authenticated using ((select private.has_establishment_role((select establishment_id from public.products where id=product_id),array['administrateur','gestion']::public.app_role[]))) with check ((select private.has_establishment_role((select establishment_id from public.products where id=product_id),array['administrateur','gestion']::public.app_role[])));
create policy "Members can read stock positions" on public.stock_positions for select to authenticated using ((select private.is_establishment_member(establishment_id)));
create policy "Management can create stock positions" on public.stock_positions for insert to authenticated with check (updated_by=(select auth.uid()) and (select private.has_establishment_role(establishment_id,array['administrateur','gestion']::public.app_role[])));
create policy "Management can update stock positions" on public.stock_positions for update to authenticated using ((select private.has_establishment_role(establishment_id,array['administrateur','gestion']::public.app_role[]))) with check (updated_by=(select auth.uid()) and (select private.has_establishment_role(establishment_id,array['administrateur','gestion']::public.app_role[])));
create policy "Members can read stock movements" on public.stock_movements for select to authenticated using ((select private.is_establishment_member(establishment_id)));
create policy "Management can record validated stock movements" on public.stock_movements for insert to authenticated with check (validated_by=(select auth.uid()) and (select private.has_establishment_role(establishment_id,array['administrateur','gestion']::public.app_role[])));
